{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "critical",
      "file": "cloud_pilot/multilingual/startup.py; cloud_pilot/live/engine.py",
      "detail": "Checkpoint namespaces bind only the evidence revision and article ID, not the approved plan or code. A newly approved plan that reuses an ID and revision can reuse old evidence, research, article and delivery checkpoints. The cached-delivery path also skips fresh PR verification.",
      "required_fix": "Bind checkpoints to immutable plan, code, rules and evidence hashes. Validate those bindings and the current PR head, diff and draft state before returning any cached delivery."
    },
    {
      "severity": "high",
      "file": ".github/workflows/cloud-pilot-manual.yml",
      "detail": "The workflow is loaded from the dispatched integration branch, while the permit checks only the separately checked-out code SHA. A changed workflow can access the environment secrets before the approved Python code checks its permit; the code SHA does not authenticate the executing workflow.",
      "required_fix": "Run the secret-bearing entry point from a protected, independently controlled workflow revision, and bind the executing workflow to the approved revision. Restrict environment and branch access accordingly."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/ledger.py; cloud_pilot/live/http.py",
      "detail": "The cap depends on a mutable branch ledger. Hash-chain and CAS checks detect corruption during normal appends, but a reset to an older valid ledger is accepted and can discard recorded spend. The ledger also requires prior spend to be zero without establishing that from independent program billing evidence.",
      "required_fix": "Anchor ledger progression in an independently protected, monotonic store or equivalent trusted control, and verify the opening balance against whole-program billing evidence before authorizing calls."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/stages.py",
      "detail": "The research gate can set WRITING_AI_READY while omitting mandatory vehicle identity fields such as body style, drivetrain and production boundary, as well as required fact and handoff fields. Literal quotation matching and a model-declared scope check do not establish that a quotation supports the asserted fact.",
      "required_fix": "Validate the complete identity lock, per-fact provenance and applicability, conflicts, time-sensitive facts, allowed/blocked lists, locks and versioned handoff fields. Stop writing when core identity or direct support remains unresolved."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/contract.py; cloud_pilot/multilingual/startup.py; cloud_pilot/live/policy.py",
      "detail": "Startup loads a fixed list of review handoffs rather than determining the latest applicable handoff. It also records a negative skill-impact check without performing one. New applicable review files in an approved main can therefore be present but omitted from the model's rules and provenance.",
      "required_fix": "Sync and verify the current main baseline, discover and bind the latest applicable review and batch evidence, and record an actual skill-impact assessment. Stop if required current material is missing or has drifted."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/engine.py; cloud_pilot/multilingual/sources.py",
      "detail": "The redirect allowlist includes every source URL in both articles. Consequently, one source may redirect to another source's URL even when no redirect was explicitly authorized, potentially attributing the returned text to the wrong declared publisher or scope.",
      "required_fix": "Authorize redirects per source, validate each final URL and publisher against that mapping, and stop on an undeclared redirect."
    },
    {
      "severity": "medium",
      "file": "cloud_pilot/multilingual/localize.py",
      "detail": "Locale review covers the structured article, but the subsequently generated Markdown adds unreviewed English metadata, source-table headings and editorial text. It can report automated multilingual drafts complete with placeholder image text and draft-only URLs, which does not satisfy the repository's complete-locale requirements.",
      "required_fix": "Review and hash the final rendered locale artifact, localize and validate all public fields and tables, and report incomplete components explicitly rather than complete until their applicable gates are met."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
